#!/bin/bash
DB="docker exec 1Panel-postgresql-pIe0 psql -U strapi -d strapi -v ON_ERROR_STOP=0"
echo "===== A. sso_invite_codes 及归属 ====="
$DB -c "SELECT c.id, c.invite_code, c.invite_type, c.use_count, c.is_active, c.created_at, lnk.creator_id FROM sso_invite_codes c LEFT JOIN sso_invite_codes_creator_lnk lnk ON lnk.sso_invite_code_id=c.id ORDER BY c.id;"
echo ""
echo "===== B. sso_referral_relations 分销关系（含两侧身份）====="
$DB -c "SELECT r.id, r.created_at, vi.inviter_id, vi2.creator_id, ie.invitee_id FROM sso_referral_relations r LEFT JOIN sso_referral_relations_inviter_lnk vi ON vi.sso_referral_relation_id=r.id LEFT JOIN sso_referral_relations_invitee_lnk ie ON ie.sso_referral_relation_id=r.id LEFT JOIN sso_referral_relations_invite_code_lnk vi2 ON vi2.sso_referral_relation_id=r.id;"
echo ""
echo "===== C. sso_invite_usages 邀请码使用 ====="
$DB -c "SELECT u.id, u.used_at, ul.user_id, ics.invite_code FROM sso_invite_usages u LEFT JOIN sso_invite_usages_user_lnk ul ON ul.sso_invite_usage_id=u.id LEFT JOIN sso_invite_usages_invite_code_lnk ic ON ic.sso_invite_usage_id=u.id LEFT JOIN sso_invite_codes ics ON ics.id=ic.sso_invite_code_id;"
echo ""
echo "===== D. activity_referral_rewards 推荐奖励 ====="
$DB -c "SELECT a.id, a.points, a.source_invite_code, a.issued_at, vi.inviter_id, ie.invitee_id FROM activity_referral_rewards a LEFT JOIN activity_referral_rewards_inviter_lnk vi ON vi.activity_referral_reward_id=a.id LEFT JOIN activity_referral_rewards_invitee_lnk ie ON ie.activity_referral_reward_id=a.id;"
echo ""
echo "===== E. zhao_point_records 共享/任务积分 ====="
$DB -c "SELECT r.id, r.action, r.points, r.dim_type, r.dim_id, r.remark, r.created_at, lnk.user_id FROM zhao_point_records r LEFT JOIN zhao_point_records_user_lnk lnk ON lnk.point_record_id=r.id WHERE r.action LIKE '%share%' OR r.action LIKE '%invite%' ORDER BY r.id DESC LIMIT 30;"
echo ""
echo "===== F. zhao_point_share_visits 分享访问归因 ====="
$DB -c "SELECT count(*) FROM zhao_point_share_visits;"
$DB -c "SELECT v.id, v.target_type, v.target_id, v.invite_code, v.created_at, lnk.inviter_id FROM zhao_point_share_visits v LEFT JOIN zhao_point_share_visits_inviter_lnk lnk ON lnk.zhao_point_share_visit_id=v.id ORDER BY v.id DESC LIMIT 15;"
echo ""
echo "===== G. activity_share 规则配置 ====="
$DB -c "SELECT id, action, points, enabled, is_one_time, limit_per_day, link_type, link_target_id, link_title FROM zhao_point_rules WHERE action='activity_share' OR action LIKE '%share%';"